import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { buildPayslip, type Employee } from "../src/payroll/payslips.ts";
import { PayslipDelivery, type EmailGateway, type PrintQueue } from "../src/payroll/delivery.ts";
import { runPayroll } from "../src/payroll/run.ts";

// Mail provider fake: addresses in `bouncing` are rejected after the SMTP round trip.
function mailer(bouncing: string[] = []): EmailGateway & { sent: string[] } {
    const m = {
        sent: [] as string[],
        async send(to: string) {
            await tick();
            if (bouncing.includes(to)) throw new Error(`550 mailbox unavailable: ${to}`);
            m.sent.push(to);
        },
    };
    return m;
}

function printer(down = false): PrintQueue & { letters: { address: string; note: string }[] } {
    const p = {
        letters: [] as { address: string; note: string }[],
        async enqueue(address: string, _body: string, note: string) {
            await tick();
            if (down) throw new Error("print vendor unavailable");
            p.letters.push({ address, note });
            return `PRN-${p.letters.length}`;
        },
    };
    return p;
}

const base = { annualSalaryCents: 6_000_000, taxRate: 0.2, pensionRate: 0.05, paperOnly: false };
const ana: Employee = { ...base, id: "e1", name: "Ana Ruiz", email: "ana@corp.example", postalAddress: "1 Elm St" };
const ben: Employee = { ...base, id: "e2", name: "Ben Ito", email: "ben@old-domain.example", postalAddress: "2 Oak Ave" };
const cy: Employee = { ...base, id: "e3", name: "Cy Moss", postalAddress: "3 Pine Rd", paperOnly: true };

test("net pay takes pension before tax", () => {
    assert.deepEqual(buildPayslip(ana, "2026-11"), {
        employeeId: "e1", period: "2026-11", grossCents: 500_000, pensionCents: 25_000, taxCents: 95_000, netCents: 380_000,
    });
});

test("an employee with an email address gets the payslip by email", async () => {
    const email = mailer();
    const print = printer();
    const receipt = await new PayslipDelivery(email, print).deliver(ana, buildPayslip(ana, "2026-11"));
    assert.deepEqual(receipt, { employeeId: "e1", channel: "email", reference: "ana@corp.example" });
    assert.equal(print.letters.length, 0);
});

test("an employee who opted out of email gets a letter", async () => {
    const print = printer();
    const receipt = await new PayslipDelivery(mailer(), print).deliver(cy, buildPayslip(cy, "2026-11"));
    assert.equal(receipt.channel, "post");
    assert.deepEqual(print.letters, [{ address: "3 Pine Rd", note: "opted out of email" }]);
});

test("a bounced email falls back to a printed letter", async () => {
    const print = printer();
    const logs: string[] = [];
    const delivery = new PayslipDelivery(mailer(["ben@old-domain.example"]), print, (l) => logs.push(l));
    const receipt = await delivery.deliver(ben, buildPayslip(ben, "2026-11")).catch((err) => {
        console.log("deliver() rejected instead of falling back:", (err as Error).message);
        throw err;
    });
    assert.deepEqual(receipt, { employeeId: "e2", channel: "post", reference: "PRN-1" });
    assert.deepEqual(print.letters, [{ address: "2 Oak Ave", note: "email failed" }]);
    assert.equal(logs.length, 1);
});

test("a payroll run delivers to everyone, falling back to post where needed", async () => {
    const email = mailer(["ben@old-domain.example"]);
    const summary = await runPayroll([ana, ben, cy], "2026-11", new PayslipDelivery(email, printer()));
    assert.deepEqual(summary.undelivered, []);
    assert.deepEqual(summary.receipts.map((r) => [r.employeeId, r.channel]), [["e1", "email"], ["e2", "post"], ["e3", "post"]]);
    assert.equal(summary.totalNetCents, 3 * 380_000);
});

test("when both email and post fail the employee is listed for HR", async () => {
    const summary = await runPayroll([ana, ben], "2026-11", new PayslipDelivery(mailer(["ben@old-domain.example"]), printer(true)));
    assert.deepEqual(summary.receipts.map((r) => r.employeeId), ["e1"]);
    assert.equal(summary.undelivered.length, 1);
    assert.equal(summary.undelivered[0].employeeId, "e2");
});

test("a letter is never queued for someone whose email went through", async () => {
    const print = printer();
    const summary = await runPayroll([ana, { ...ben, email: "ben@corp.example" }], "2026-11", new PayslipDelivery(mailer(), print));
    assert.equal(print.letters.length, 0);
    assert.deepEqual(summary.receipts.map((r) => r.channel), ["email", "email"]);
});
